package store
import("context";"errors";"fmt";"time";"github.com/google/uuid";"github.com/jackc/pgx/v5";"github.com/SupanatSMOST/tennis-tracker/backend/internal/cvresult";"github.com/SupanatSMOST/tennis-tracker/backend/internal/model")
// InsertCVRecords verifies event provenance independently and inserts immutable CV records atomically. Record ID conflicts are replay-safe; differing payload conflicts fail rather than overwrite.
func(s *Store)InsertCVRecords(ctx context.Context,matchID,userID uuid.UUID,recs []model.Record,events []cvresult.Event)error{eligible:=map[string]cvresult.Event{};for _,e:=range events{if e.ReviewStatus=="accepted"||e.ReviewStatus=="corrected"{eligible[e.EventID]=e}};tx,err:=s.pool.Begin(ctx);if err!=nil{return err};defer tx.Rollback(ctx);var ended *time.Time;err=tx.QueryRow(ctx,`SELECT ended_at FROM match WHERE match_id=$1 AND user_id=$2 FOR UPDATE`,matchID,userID).Scan(&ended);if errors.Is(err,pgx.ErrNoRows){return ErrMatchNotFound};if err!=nil{return err};if ended!=nil{return ErrMatchAlreadyEnded};seen:=map[uuid.UUID]bool{};for _,r:=range recs{if r.Source!="cv"||r.MatchID!=matchID||seen[r.RecordID]{return errors.New("invalid or duplicate CV record")};seen[r.RecordID]=true;found:=false;for _,e:=range eligible{if e.Zone!=nil&&*e.Zone==r.Zone&&e.EventType=="bounce"{found=true;break}};if !found||!validZone(r.Zone){return errors.New("record has no eligible reviewed event or valid zone")};if r.TsMs==nil{return errors.New("CV record timestamp required")}};for _,r:=range recs{tag,err:=tx.Exec(ctx,`INSERT INTO record(record_id,match_id,zone,court_x,court_y,ts_ms,source) VALUES($1,$2,$3,$4,$5,$6,'cv') ON CONFLICT(record_id) DO NOTHING`,r.RecordID,matchID,r.Zone,r.CourtX,r.CourtY,r.TsMs);if err!=nil{return err};if tag.RowsAffected()==0{var zone,source string;var ts *int32;err=tx.QueryRow(ctx,`SELECT zone,source,ts_ms FROM record WHERE record_id=$1`,r.RecordID).Scan(&zone,&source,&ts);if err!=nil{return err};if zone!=r.Zone||source!="cv"||ts==nil||*ts!=*r.TsMs{return fmt.Errorf("deterministic CV record ID collision with different content")}}};return tx.Commit(ctx)}
func validZone(z string)bool{switch cvresult.Zone(z){case cvresult.ZoneFrontCourtLeft,cvresult.ZoneFrontCourtRight,cvresult.ZoneBaselineLeft,cvresult.ZoneBaselineRight,cvresult.ZoneOutLeft,cvresult.ZoneOutRight,cvresult.ZoneOutBehind:return true};return false}
